package com.acme.core.infrastructure.persistence;

import com.acme.core.application.warehouselite.WarehouseLitePort;
import com.acme.core.application.warehouselite.WarehouseLiteService;
import com.acme.core.application.organization.DepartmentPort;
import com.acme.core.application.dictionary.DictionaryPort;
import com.acme.core.infrastructure.persistence.mapper.WarehouseLiteMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * WarehouseLite bean wiring (generated by engineering-platform Generic Module Generator).
 */
@Configuration
public class WarehouseLiteBeansConfig {

    @Bean
    public WarehouseLitePort warehouseLitePort(WarehouseLiteMapper mapper, DepartmentPort departmentPort) {
        return new MybatisWarehouseLiteRepository(mapper, departmentPort);
    }

    @Bean
    public WarehouseLiteService warehouseLiteService(WarehouseLitePort port, DictionaryPort dictionaryPort) {
        return new WarehouseLiteService(port, dictionaryPort);
    }
}
